import test from 'node:test';
import assert from 'node:assert/strict';
import {createActionArbiter,createAtomicEffectHost,createExactMemoryStore} from './foundation.js';
const clone=x=>JSON.parse(JSON.stringify(x));
function fixture(store=createExactMemoryStore()){
 let live={hp:{a:20,b:20},mana:5,used:false,notes:[]};
 const host=createAtomicEffectHost({battleId:'fixture',store,capture:()=>clone(live),restore:s=>{live=clone(s);},applyEffect:e=>{const before=live.hp[e.targetId];live.hp[e.targetId]=Math.max(0,before-e.amount);live.notes.push(e.eventId);return {eventId:e.eventId,targetId:e.targetId,kind:e.kind,before,after:live.hp[e.targetId],actual:before-live.hp[e.targetId],maximum:before};}});
 const action={id:'fixture:1:ult:1',unitId:1,sequence:1,skillId:'test_only_neutral',variantId:'fixture',commitTick:0,resolveTick:2,recoveryUntil:3,manaCost:2,intents:['a','b'].map((targetId,i)=>({eventId:`fixture:1:ult:1:${i}`,targetId,sourceId:1,kind:'damage',amount:3}))};
 return {host,store,action,get live(){return live;},commit(){return host.prepare(action,()=>{live.mana-=2;live.used=true;});}};
}
test('arbiter rejects overlapping skills while independent units and natural expiry work',()=>{const a=createActionArbiter('battle');a.claim({unitId:1,id:'basic',owner:'class',from:1,until:5});assert.equal(a.canStart(1,'ultimate',2),false);assert.equal(a.canStart(2,'ultimate',2),true);assert.throws(()=>a.claim({unitId:1,id:'ultimate',owner:'ultimate',from:2,until:6}),/occupied/);const s=a.snapshot();assert.deepEqual(a.snapshot(),s);assert.equal(a.canStart(1,'ultimate',5),true);a.claim({unitId:1,id:'ultimate',owner:'ultimate',from:5,until:6});a.restore(s);assert.equal(a.canStart(1,'ultimate',2),false);});
test('frozen intents, paid commit, effects and exact retries',()=>{const f=fixture();f.commit();assert.equal(f.live.mana,3);const r=f.host.resolve(f.action.id);assert.deepEqual(f.live.hp,{a:17,b:17});assert.equal(r.receipts.length,2);f.commit();assert.deepEqual(f.host.resolve(f.action.id),r);assert.equal(f.live.mana,3);assert.equal(f.live.notes.length,2);assert.throws(()=>f.host.prepare({...f.action,manaCost:3},()=>{}),/collision/);});
test('effect exception restores whole host and durable prepared IDs for restart',()=>{const f=fixture();f.commit();let count=0;const failing=createAtomicEffectHost({battleId:'fixture',store:f.store,capture:()=>clone(f.live),restore:s=>{Object.keys(f.live).forEach(k=>delete f.live[k]);Object.assign(f.live,clone(s));},applyEffect:e=>{f.live.notes.push(e.eventId);f.live.hp[e.targetId]-=3;if(++count===2)throw Error('injected');return {eventId:e.eventId,targetId:e.targetId,kind:e.kind,before:20,after:17,actual:3,maximum:20};}});assert.throws(()=>failing.resolve(f.action.id),/injected/);assert.deepEqual(f.live.hp,{a:20,b:20});assert.deepEqual(f.live.notes,[]);const resumed=fixture(f.store);resumed.host.resolve(f.action.id);assert.deepEqual(resumed.live.hp,{a:17,b:17});assert.equal(resumed.live.mana,3);});
test('commit failure rolls back payment; lost acknowledgement reconciles; stale parent rejects',()=>{const base=createExactMemoryStore();let mode='ok';const store={load:()=>base.load(),commit:(p,n)=>{if(mode==='before')throw Error('before');base.commit(p,n);if(mode==='after')throw Error('after');}};const f=fixture(store);mode='before';assert.throws(()=>f.commit(),/before/);assert.equal(f.live.mana,5);mode='after';f.commit();assert.equal(f.live.mana,3);mode='ok';const foreign=base.load();foreign.host.notes.push('foreign');base.replaceForTest(foreign);assert.throws(()=>f.host.resolve(f.action.id),/conflict/);assert.deepEqual(f.live.hp,{a:20,b:20});});
test('non-finite, wrong target and false positive delta receipts rollback',()=>{for(const defect of ['NaN','wrong-target','false-delta']){const f=fixture();f.commit();let state=clone(f.live);const host=createAtomicEffectHost({battleId:'fixture',store:f.store,capture:()=>clone(state),restore:s=>{state=clone(s);},applyEffect:e=>({eventId:e.eventId,targetId:defect==='wrong-target'?'b':e.targetId,kind:e.kind,before:20,after:20,actual:defect==='NaN'?NaN:1,maximum:20})});assert.throws(()=>host.resolve(f.action.id),/receipt|finite/);assert.deepEqual(state.hp,{a:20,b:20});}});
test('settled write with temporarily unreadable acknowledgement reconciles before any retry',()=>{const base=createExactMemoryStore();let armed=false,denyOnce=false;const store={load(){if(denyOnce){denyOnce=false;throw Error('unreadable');}return base.load();},commit(p,n){base.commit(p,n);if(armed&&Object.values(n.records).some(r=>r.status==='settled')){armed=false;denyOnce=true;throw Error('lost-ack');}}};const f=fixture(store);f.commit();armed=true;assert.throws(()=>f.host.resolve(f.action.id),/outcome unknown/);assert.deepEqual(f.live.hp,{a:20,b:20});const r=f.host.resolve(f.action.id);assert.equal(r.status,'settled');assert.deepEqual(f.live.hp,{a:17,b:17});assert.equal(f.live.notes.length,2);assert.equal(f.live.mana,3);});
test('snapshots are observational and foreign configuration checkpoint is rejected',()=>{const f=fixture();f.commit();const before=f.store.load();for(let i=0;i<10;i++)f.host.snapshot();assert.deepEqual(f.store.load(),before);assert.throws(()=>createAtomicEffectHost({battleId:'fixture',identity:{other:true},store:f.store,capture:()=>f.live,restore:()=>{},applyEffect:()=>{}}),/foreign/);});

test('UA2 delayed batches commit only due frozen intents and retain exact prior receipts across restart',()=>{let hp=10;const store=createExactMemoryStore(),options={battleId:'delayed',capture:()=>({hp}),restore:s=>{hp=s.hp;},applyEffect:e=>{const before=hp;hp-=e.amount;return {eventId:e.eventId,targetId:e.targetId,kind:e.kind,before,after:hp,actual:e.amount,maximum:before};},store};const host=createAtomicEffectHost(options),a={id:'delayed:1',unitId:1,sequence:1,skillId:'ult_mage',variantId:'ember_tactician',commitTick:0,resolveTick:3,recoveryUntil:5,manaCost:0,intents:[{eventId:'delayed:1:0',sourceId:1,targetId:2,kind:'damage',amount:1,dueTick:3},{eventId:'delayed:1:1',sourceId:1,targetId:2,kind:'damage',amount:1,dueTick:6}]};host.prepare(a,()=>{});host.resolve(a.id,3);assert.equal(hp,9);assert.equal(host.snapshot().records[0].receipts.length,1);const cold=createAtomicEffectHost({...options,store:createExactMemoryStore(host.exportCheckpoint())});cold.resolve(a.id,5);assert.equal(hp,9);cold.resolve(a.id,6);assert.equal(hp,8);assert.equal(cold.snapshot().records[0].receipts.length,2);cold.resolve(a.id,6);assert.equal(hp,8);});
